import {React, useState} from "react";
import {useStateMachine} from "little-state-machine";
import {Link, useParams} from "react-router-dom";
import './theme.css';
import './ThankYouPage.css';
import {DEFAULT_LANG, locale_text, locale_text_raw} from "./lang";
import axios from "axios";

const ReturnButton = (opts) => {
    return (
        <Link to="/">
            <button className="button-generic button-stick-to-center thankyou-button" {...opts}>
                {opts.children}
            </button>
        </Link>
    );
};

const SubmitButton = (opts) => {
    return (
        <button className="button-generic thankyou-send-button" {...opts}>
            {opts.children}
        </button>
    );
};

export function ThankYouPage() {
    const {surveyid} = useParams();
    const {state} = useStateMachine();
    const lang = state['language'] || DEFAULT_LANG;

    // Move all hooks to the top - before any conditional logic
    const [name, setName] = useState("");
    const [email, setEmail] = useState("");
    const [message, setMessage] = useState("");

    // Check if user is not eligible (answered "No" to residency)
    const isNotEligible = surveyid === 'not-eligible';

    const submitContactInfo = () => {
        const _data = {
            name: name, 
            email: email, 
            message: message
        };
        const data = {};
        data[surveyid] = _data;

        console.log("Contact info (offline mode):", data);
        alert('Contact form submitted! (Test mode)');

        // Clear the form
        setName("");
        setEmail("");
        setMessage("");
    };

    // Conditional return after all hooks
    if (isNotEligible) {
        return (
            <div className="container-page-root">
                <div className="thank-you-page-container">
                    <div className="thank-you-content-wrapper thank-you-not-eligible">
                        <h1 className="title-text thank-you-title-text-h1">
                            {locale_text(lang, 'thank-you-not-eligible-title')}
                        </h1>
                        <p className="thank-you-description-text">
                            {locale_text(lang, 'thank-you-not-eligible-description')}
                        </p>
                        <Link to="/">
                            <button className="button-generic button-stick-to-center thankyou-button">
                                {locale_text(lang, 'thank-you-button-start-again')}
                            </button>
                        </Link>
                    </div>
                </div>
            </div>
        );
    }

    // Regular thank you page for completed surveys
    return (
        <div className="container-page-root">
            <div className="thank-you-page-container">
                <div className="thank-you-content-wrapper">
                    {/* Main thank you section */}
                    <div className="thank-you-main-section">
                        <h1 className="title-text thank-you-title-text-h1">
                            {locale_text(lang, 'thank-you-title')}
                        </h1>
                        <p className="thank-you-description-text">
                            {locale_text(lang, 'thank-you-description')}
                        </p>
                        <ReturnButton>
                            {locale_text(lang, 'thank-you-button-start-again')}
                        </ReturnButton>
                    </div>

                    {/* Contact form section */}
                    <div className="thank-you-form">
                        <div className="thank-you-form-section">
                            <p className="thank-you-description-text">
                                {locale_text(lang, 'thank-you-form-description')}
                            </p>

                            <form>
                                <div className="thankyou-input-field">
                                    <input 
                                        type="text" 
                                        placeholder={locale_text_raw(lang, 'thank-you-form-full-name')}
                                        value={name} 
                                        onChange={(e) => setName(e.target.value)}
                                    />
                                </div>

                                <div className="thankyou-input-field">
                                    <input 
                                        type="email" 
                                        placeholder={locale_text_raw(lang, 'thank-you-form-email')}
                                        value={email} 
                                        onChange={(e) => setEmail(e.target.value)}
                                    />
                                </div>

                                <div className="thankyou-input-field">
                                    <textarea
                                        placeholder={locale_text_raw(lang, 'thank-you-form-message')}
                                        value={message} 
                                        onChange={(e) => setMessage(e.target.value)}
                                    />
                                </div>

                                <SubmitButton onClick={submitContactInfo}>
                                    {locale_text(lang, 'thank-you-form-submit-button')}
                                </SubmitButton>
                            </form>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
